// 隔离共享候选：三个本人命令均经原守卫/完整历史，只有真实接受会替换原Office。
#include "political_term_handover_world.hpp"
#include "world_bundle.hpp"
namespace hanmo::resident {namespace {
// 空账同样验证原作者首府归属，不能让遗漏管辖的目录在新局获得默认合法身份。
Status available(const WorldBundle& w){if(!w.catalog->political_term_handovers||!w.political_term_handovers||!w.catalog->political_successions||!w.political_successions||!w.catalog->political_successor_rounds||!w.political_successor_rounds||!w.politics_enabled()||!w.catalog->organization||!w.catalog->organization->enabled||!w.family_life_enabled()||!w.catalog->common)return common_failure("PoliticalTermHandoverProfileRequired");for(const auto& row:w.catalog->political_term_handovers->policies.rows()){const auto* round=w.catalog->political_successor_rounds->policies.find(row.second.successor_round_policy_id);const auto* p=round?w.catalog->political_successions->policies.find(round->succession_policy_id):nullptr;const auto* j=p?w.catalog->politics->jurisdictions.find(p->jurisdiction_id):nullptr;if(!p||!j||j->revision!=0||j->office_id!=p->leader_office_id||j->seat_place_id!=p->seat_place_id||j->political_organization_id!=p->organization_id||j->controlling_organization_id!=p->organization_id)return common_failure("PoliticalTermHandoverOriginalSeatRequired",row.first);}return common_success();}
// 同命令名不能替代实际明细；接受还必须携同一次原Office变更来源。
bool actual_result(const CommitResult& r,const StableId& source,const StableId& office){if(!r.ok||!r.details)return false;const auto* e=std::get_if<PoliticsEffects>(&r.details->data);return e&&valid_political_term_handover_effect(r.kind,*e)&&e->fact_ids==std::vector<StableId>{source}&&e->receipt_ids==(office.empty()?std::vector<StableId>{}:std::vector<StableId>{office});}
// 玩家本人身份不能代原共同生命、行动及舟上等守卫；两个NPC入口另在写前拒本命令。
Status player(const WorldBundle& w,const StableId& actor,const PoliticalTermHandoverCommand& c){auto v=command_common_guard(w,actor,political_term_handover_command_kind(c));if(!v.ok)return v;return actor==w.common.state().metadata.player_actor_id?common_success():common_failure("PoliticalTermHandoverPlayerCommandRequired");}
}
// 旧profile返回空借口；启用者只映射原Office原因，绝不在此调用完整新轮/交接验证。
PoliticalTermHandoverHeadRead political_term_handover_head_read_world(const WorldBundle& w){if(!w.catalog->political_term_handovers&&!w.political_term_handovers)return {};return [&w](const PoliticalSuccessionPolicy& p,const PoliticalSuccessionOfficeSource& office)->Outcome<std::optional<PoliticalHeadSource>>{if(!w.catalog->political_term_handovers||!w.political_term_handovers||!w.catalog->political_successor_rounds||!w.political_successor_rounds)return {false,{},common_failure("PoliticalTermHandoverProfileRequired").error};return read_political_term_handover_head_source(w.common,*w.catalog->political_term_handovers,*w.political_term_handovers,*w.catalog->political_successor_rounds,p,office);};}
// 原占领/辖区与原任期根先构造，业务上下文只同步借本holder的稳定成员。
PoliticalTermHandoverWorldAccess::PoliticalTermHandoverWorldAccess(const WorldBundle& w)
 :world_(w),military_(w.political_takeover_enabled()?std::optional<MilitaryAccess>{w.services.military_access()}:std::nullopt),
 occupations_(w.political_takeover_enabled()?std::optional<PoliticalSuccessionOccupationContext>{PoliticalSuccessionOccupationContext{w.political_takeover,*w.catalog->political_takeover,w.military,*w.catalog->military,*military_}}:std::nullopt),
 territory_{w.common,w.politics,*w.catalog->politics,occupations_?&*occupations_:nullptr},
 heads_{w.common,w.organization,*w.catalog->organization,*w.catalog->political_successions,w.political_successions->nominations,w.political_successions->accessions,w.catalog->political_head_handovers.get(),w.political_head_handovers?&*w.political_head_handovers:nullptr,political_term_handover_head_read_world(w)},
 rules_{w.common,*w.catalog->common,w.organization,*w.catalog->organization,w.local_economy,w.services,heads_,*w.catalog->political_successor_rounds,*w.political_successor_rounds,*w.catalog->political_term_handovers,*w.political_term_handovers,w.family_death_read(),[this](const PoliticalSuccessionPolicy& p,Integer tick,const StableId& fact){return validate_political_term_handover_seat(territory_,p,tick,fact);},[&w](Integer tick,const StableId& fact){return read_political_term_handover_player_before_fact(w.common,w.family,w.family_legacy_enabled()?&w.family_legacy:nullptr,tick,fact);}},context_{rules_,actual_result}{}
Outcome<std::unique_ptr<PoliticalTermHandoverWorldAccess>> PoliticalTermHandoverWorldAccess::create(const WorldBundle& w){auto v=available(w);if(!v.ok)return {false,{},v.error};return {true,std::unique_ptr<PoliticalTermHandoverWorldAccess>{new PoliticalTermHandoverWorldAccess(w)},{}};}
// 原Organization、生命、Family/Born/Legacy、首轮与新轮继位完整史先验后才检查本独立段。
Status validate_political_term_handover_world(const WorldBundle& w){auto v=validate_political_term_handover_layout(w.common,w.catalog->identity.module_versions,w.political_term_handovers?&*w.political_term_handovers:nullptr);if(!v.ok)return v;if(bool(w.catalog->political_term_handovers)!=w.political_term_handovers.has_value())return common_failure("PoliticalTermHandoverProfileMismatch");if(!w.catalog->political_term_handovers)return common_success();auto read=PoliticalTermHandoverWorldAccess::create(w);if(!read.ok)return {false,{},read.error};return validate_political_term_handovers(read.value->context());}
Outcome<PoliticalTermHandoverQuote> prepare_political_term_handover_world(const WorldBundle& w,const StableId& actor,const PoliticalTermHandoverCommand& c){auto v=player(w,actor,c);if(!v.ok)return {false,{},v.error};auto read=PoliticalTermHandoverWorldAccess::create(w);if(!read.ok)return {false,{},read.error};return preview_political_term_handover_business(read.value->context(),actor,c);}
Outcome<PoliticsEffects> commit_political_term_handover_world(WorldBundle& w,const StableId& actor,const PoliticalTermHandoverCommand& c,const PoliticalTermHandoverQuote& q){auto v=player(w,actor,c);if(!v.ok)return {false,{},v.error};auto read=PoliticalTermHandoverWorldAccess::create(w);if(!read.ok)return {false,{},read.error};auto r=apply_political_term_handover_business_in_candidate(w.common,w.organization,*w.political_term_handovers,read.value->context(),actor,c,q);if(!r.ok)return {false,{},r.error};return {true,{{},{r.value.source_fact_id},r.value.office_change_fact_id.empty()?std::vector<StableId>{}:std::vector<StableId>{r.value.office_change_fact_id}},{}};}
Outcome<BoundaryValue> query_political_term_handover_world(const WorldBundle& w,const StableId& place,Integer cursor){auto read=PoliticalTermHandoverWorldAccess::create(w);if(!read.ok)return {false,{},read.error};return query_political_term_handovers(read.value->context(),place,cursor);}
Status bind_political_term_handover_result_world(WorldBundle& w,const StableId& source,const StableId& actor,Integer request,const CommitResult& result){if(!w.catalog->political_term_handovers||!w.political_term_handovers||source.empty()||!is_political_term_handover_command(result.kind))return common_failure("PoliticalTermHandoverNewSourceRequired");return bind_political_term_handover_player_result(w.common,*w.political_term_handovers,source,actor,request,result,actual_result);}
}
